import * as T from './vendor/three.module.js';
export function createSharedTree(scene){
 const root=new T.Group();root.name='community-tree-decorations';root.position.set(108,0,35);scene.add(root);
 const material=new T.MeshPhysicalMaterial({color:'#ffffff',roughness:.18,metalness:.26,clearcoat:1,iridescence:.85,iridescenceIOR:1.32,flatShading:true});
 const setting=new T.MeshStandardMaterial({color:'#ffe6ad',roughness:.26,metalness:.72});
 function joined(parts){const attributes={position:[],normal:[],uv:[]};for(const part of parts){const geo=part.index?part.toNonIndexed():part;for(const name in attributes)attributes[name].push(...geo.attributes[name].array);if(geo!==part)geo.dispose();part.dispose();}const geo=new T.BufferGeometry();for(const name in attributes)geo.setAttribute(name,new T.Float32BufferAttribute(attributes[name],name==='uv'?2:3));return geo;}
 function hanger(y){return [new T.CylinderGeometry(.075,.105,.11,8).translate(0,y,0),new T.TorusGeometry(.085,.014,5,20).translate(0,y+.14,0)];}
 // A faceted jewel and an eight-ray frost crystal share the existing API kinds.
 const jewel=new T.IcosahedronGeometry(.43,1);jewel.scale(1,1.1,1);
 const starPositions=[],starUvs=[];
 for(let i=0;i<16;i++){const a=i*Math.PI/8+Math.PI/2,b=(i+1)*Math.PI/8+Math.PI/2,r=i%2?.17:i%4?.4:.61,s=(i+1)%2?.17:(i+1)%4?.4:.61;for(const face of [1,-1]){const points=face===1?[[0,0,.15],[Math.cos(a)*r,Math.sin(a)*r,.015],[Math.cos(b)*s,Math.sin(b)*s,.015]]:[[0,0,-.1],[Math.cos(b)*s,Math.sin(b)*s,.015],[Math.cos(a)*r,Math.sin(a)*r,.015]];for(const p of points){starPositions.push(...p);starUvs.push(p[0]+.5,p[1]+.5);}}}
 const frost=new T.BufferGeometry();frost.setAttribute('position',new T.Float32BufferAttribute(starPositions,3));frost.setAttribute('uv',new T.Float32BufferAttribute(starUvs,2));frost.computeVertexNormals();
 const belt=new T.TorusGeometry(.435,.012,4,32);belt.rotateX(Math.PI/2);
 const ballFrame=joined([...hanger(.5),belt]);
 const starFrame=joined([...hanger(.64),new T.OctahedronGeometry(.115).translate(0,0,.18)]);
 const meshes={ball:new T.InstancedMesh(jewel,material,160),star:new T.InstancedMesh(frost,material,160)};
 const frames={ball:new T.InstancedMesh(ballFrame,setting,160),star:new T.InstancedMesh(starFrame,setting,160)};
 for(const m of [...Object.values(meshes),...Object.values(frames)]){m.count=0;m.frustumCulled=false;root.add(m);}
 const dummy=new T.Object3D(),tint=new T.Color();let signature='',kind='ball',color='#cc6b73',busy=false,lastAdded='',opened=false;
 const tray=document.createElement('div');tray.id='tree-tools';tray.hidden=true;tray.setAttribute('role','group');tray.setAttribute('aria-label','트리 장식');
 tray.innerHTML='<div class="tree-palette"><button data-kind="ball" aria-label="볼 장식" aria-pressed="true"><svg viewBox="0 0 24 24"><path d="M10 5V3h4v2"/><circle cx="12" cy="14" r="8"/><path d="M8 10c2-2 4-2 6-1"/></svg></button><button data-kind="star" aria-label="별 장식" aria-pressed="false"><svg viewBox="0 0 24 24"><path d="m12 2 2.9 6.5L22 10l-5.2 4.7.9 7.3-5.7-3.7L6.3 22l.9-7.3L2 10l7.1-1.5Z"/></svg></button><i></i><button data-color="#cc6b73" style="--swatch:#cc6b73" aria-label="로즈" aria-pressed="true"></button><button data-color="#e5bb6b" style="--swatch:#e5bb6b" aria-label="골드" aria-pressed="false"></button><button data-color="#b8cfd1" style="--swatch:#b8cfd1" aria-label="아이스" aria-pressed="false"></button><button data-add aria-label="장식 달기"><svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg></button><button data-undo aria-label="마지막 장식 취소" disabled><svg viewBox="0 0 24 24"><path d="M4 5v6h6M4.5 10a8 8 0 1 1 .5 7"/></svg></button><button data-close aria-label="꾸미기 닫기"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg></button></div><p role="status">트리를 눌러 달기</p>';
 document.body.append(tray);const status=tray.querySelector('p');
 const room=()=>window.sharedRoom?.()||new URL(location.href).searchParams.get('room')||'winter-plaza';
 function render(items){const next=JSON.stringify(items);if(next===signature)return;signature=next;const counts={ball:0,star:0};for(const item of items){const m=meshes[item.kind];if(!m||counts[item.kind]>=160)continue;const t=(item.height-2.3)/(32*.82),r=32*.29*(1-t*.94)+.25;dummy.position.set(Math.cos(item.angle)*r,item.height,Math.sin(item.angle)*r);dummy.rotation.set(0,Math.PI/2-item.angle,0);dummy.updateMatrix();const index=counts[item.kind]++;m.setMatrixAt(index,dummy.matrix);frames[item.kind].setMatrixAt(index,dummy.matrix);m.setColorAt(index,tint.set(item.color));}for(const [key,m]of Object.entries(meshes)){m.count=counts[key];m.instanceMatrix.needsUpdate=true;if(m.instanceColor)m.instanceColor.needsUpdate=true;frames[key].count=counts[key];frames[key].instanceMatrix.needsUpdate=true;}}
 async function sync(){if(!window.labSocialJoined)return;if(document.hidden)return;try{const r=await fetch('/api/tree?room='+encodeURIComponent(room()),{signal:AbortSignal.timeout(8000)});if(r.ok)render((await r.json()).decorations);}catch{}}
 async function mutate(method,body){const response=await fetch('/api/tree',{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(8000)}),data=await response.json();if(!response.ok)throw Error(data.error||'연결을 확인해 주세요.');return data;}
 async function add(angle,height){if(!opened||busy)return;busy=true;status.textContent='';try{await window.joinSharedActivity();const data=await mutate('POST',{kind,color,angle,height});lastAdded=data.id;tray.querySelector('[data-undo]').disabled=false;await sync();status.textContent='트리를 눌러 달기';}catch(e){status.textContent=e.message;}finally{busy=false;}}
 window.placeTreeDecoration=point=>add(Math.atan2(point.z-35,point.x-108),Math.max(3,Math.min(27,point.y)));
 window.treeDecorationActive=()=>opened;
 tray.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.kind){kind=b.dataset.kind;tray.querySelectorAll('[data-kind]').forEach(n=>n.setAttribute('aria-pressed',n===b));}else if(b.dataset.color){color=b.dataset.color;tray.querySelectorAll('[data-color]').forEach(n=>n.setAttribute('aria-pressed',n===b));}else if(b.hasAttribute('data-add')){const p=window.labPlayerState||{x:108,z:53};add(Math.atan2(p.z-35,p.x-108),5+Math.random()*19);}else if(b.hasAttribute('data-undo')&&lastAdded&&!busy){busy=true;try{await mutate('DELETE',{id:lastAdded});lastAdded='';b.disabled=true;await sync();}catch(e){status.textContent=e.message;}finally{busy=false;}}else if(b.hasAttribute('data-close')){opened=false;tray.hidden=true;}});
 window.addEventListener('lab:tree-open',()=>{opened=true;tray.hidden=false;status.textContent='트리를 눌러 달기';sync();});
 window.addEventListener('keydown',e=>{if(e.key==='Escape'){opened=false;tray.hidden=true;}});
 window.addEventListener('lab:room',()=>{lastAdded='';tray.querySelector('[data-undo]').disabled=true;render([]);sync();});setInterval(sync,2000);sync();return{update(x,z){if(opened&&Math.hypot(x-108,z-35)>38){opened=false;tray.hidden=true;}}};
}
